{
  "case_id": "xsu_sg_008_completed_treatment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer kernen: epikrise/afslutningsbrev som udgangspunkt ved afsluttet behandling. Men det tilføjer et krav om journal fra de seneste 2-3 år, som ikke findes i kilderne. Det opstiller også journal fra egen læge som et fast krav ved siden af epikrisen, så det ligner et kumulativt krav. Kilderne kræver som minimum journaler fra egen læge, speciallæge, hospital eller ambulant klinik. Dermed rammer svaret rubrikkens væsentlige fejl om kumulative behandlertyper."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med i tilsvarende form: journalmateriale fra læge, hospital eller klinik, beskrivelse af funktionsnedsættelsen og epikrise/afslutningsnotat som udgangspunkt ved afsluttet behandling. Formuleringen af de to første er upræcis (kumulativ ramme, 'varig' nævnes ikke eksplicit), men elementerne er til stede."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilken lægelig dokumentation der skal vedlægges ved afsluttet behandling."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til identificerbare kilder: SU's dokumentationsside/vejledning og SU-loven LBK 395/2023 § 54 og § 46 h. Flere centrale udsagn er dog markeret '(uden kilde)', og fodnoterne er uspecifikke. Kriteriet er derfor kun knapt opfyldt."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "De anførte lovbestemmelser, SU-loven § 54 og § 46 h, er ikke de relevante kilder for dokumentationskravet. De ligger uden for den frosne kildeafgrænsning, hvor SU-bekendtgørelsen § 37 og vejledningens afsnit 4.1 gælder. Den 'dokumentationsside' og de fodnoter, svaret nævner, kan ikke identificeres i materialet."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "§ 54 og § 46 h understøtter ikke påstandene om epikrise, journal fra egen læge, 2-3 år eller indholdet af dokumentationen. Det er kun de uciterede passager, der svarer til vejledningen."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uden støtte i materialet 'journal fra de sidste 2-3 år'. Det tilføjer også en liste over, hvad dokumentationen 'mindst bør vise' (diagnose, hverdagspåvirkning, behandling, erhvervsevne), en tommelfingerregel om yderligere dokumentation og påstanden om, at SU kan 'fastsætte krav til dokumentation'."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "'Som udgangspunkt' er bevaret ved epikrisen. Svaret fremhæver ikke, at titlen på dokumentet ikke afgør tilstrækkeligheden, eller at en epikrise kan indgå som journalmateriale. Behandlertyperne fremstilles ikke som alternativer, og afvisningsfølgen er blødt op til 'kan risikere at blive afvist'."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: først hovedreglen, derefter specificering og tommelfingerregel. Konklusionen følger af de trin, der er vist, selv om trinene indeholder uunderstøttede tilføjelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger 'skal' om journal fra egen læge for 2-3 år og om, hvad der skal vedlægges, selv om kilden kun kræver journaler fra en af flere behandlertyper. Det blander 'skal', 'bør' og 'normalt' uden at følge kildens modalitet."
    }
  },
  "xhaile_coverage": {
    "A30": {
      "label": "yes",
      "reason": "Svaret angiver, at man som udgangspunkt skal vedlægge epikrise/afslutningsnotat, når behandlingen er afsluttet."
    },
    "A32": {
      "label": "yes",
      "reason": "Svaret nævner epikrise/afslutningsnotat som en del af dokumentationen ved afsluttet behandling og bevarer 'som udgangspunkt'. Det tilføjer dog yderligere krav, som kilden ikke har."
    }
  },
  "overall_notes": "Svaret rammer hovedpunktet om epikrise/afslutningsbrev som udgangspunkt. Det skader sig selv ved at opfinde et 2-3-årskrav, ved at fremstille journal fra egen læge som fast kumulativt krav og ved at citere irrelevante lovparagraffer. De vigtige kvalifikationer fra rubrikken mangler. C04 er vurderet met, fordi der trods alt er identificerbare kilder; udsagnene markeret '(uden kilde)' trækker i modsat retning."
}

